import type { GeneratedTestCase } from './types.js';

/**
 * Emits a Playwright API test file for one endpoint's generated cases.
 *
 * State-dependent endpoints (those with a {petId}-style path param that
 * mutates or reads a specific resource) are made SELF-CONTAINED: the test
 * provisions its own resource in a setup step so cases never depend on
 * seed data or the execution order of other tests.
 */
export function emitPlaywrightSpec(endpointId: string, cases: GeneratedTestCase[]): string {
  const header = `/**
 * AUTO-GENERATED by ai-qa-quality-platform.
 * Source endpoint: ${endpointId}
 * DO NOT EDIT BY HAND — regenerate with: npm run generate:tests
 */
import { test, expect } from '@playwright/test';

const BASE_URL = process.env.API_BASE_URL || 'http://localhost:3000';

function buildUrl(path: string, pathParams?: Record<string, unknown>, query?: Record<string, unknown>) {
  let url = path;
  for (const [k, v] of Object.entries(pathParams ?? {})) {
    url = url.replace(\`{\${k}}\`, encodeURIComponent(String(v)));
  }
  const qs = new URLSearchParams();
  for (const [k, v] of Object.entries(query ?? {})) {
    if (v === undefined || v === null) continue;
    qs.append(k, String(v));
  }
  const q = qs.toString();
  return \`\${BASE_URL}\${url}\${q ? \`?\${q}\` : ''}\`;
}

/** Creates a throwaway pet and returns its id (for self-contained tests). */
async function createPet(request: any, overrides: Record<string, unknown> = {}): Promise<number> {
  const res = await request.post(\`\${BASE_URL}/pets\`, {
    data: { name: \`qa-\${Date.now()}-\${Math.random().toString(36).slice(2, 8)}\`, status: 'available', ...overrides },
    headers: { 'Content-Type': 'application/json' },
  });
  const body = await res.json();
  return body.id as number;
}

`;

  const body = cases.map((c) => emitSingleTest(c)).join('\n\n');
  return header + body + '\n';
}

/** True when the case targets a specific resource id that must exist. */
function needsProvisioning(c: GeneratedTestCase): boolean {
  const hasPathId = /\{[^}]+\}/.test(c.path);
  if (!hasPathId) return false;
  // A "missing required path param" or "unknown id" negative test does NOT
  // need a provisioned resource — it deliberately omits/forges the id.
  const name = c.name.toLowerCase();
  if (name.includes('missing required') || name.includes('unknown') || name.includes('not found')) {
    return false;
  }
  return true;
}

function emitSingleTest(c: GeneratedTestCase): string {
  const expected = Array.isArray(c.expectedStatus) ? c.expectedStatus : [c.expectedStatus];
  const expectedExpr =
    expected.length === 1
      ? `res.status() === ${expected[0]}`
      : `[${expected.join(', ')}].includes(res.status())`;

  const headers = { 'Content-Type': 'application/json', ...(c.headers ?? {}) };

  const assertionLines = (c.assertions ?? [])
    .map((a) => `  // assertion: ${a}`)
    .join('\n');

  if (needsProvisioning(c)) {
    // Replace the first {param} with a freshly created pet id.
    const paramMatch = c.path.match(/\{([^}]+)\}/);
    const paramName = paramMatch ? paramMatch[1] : 'id';
    const otherPathParams = { ...(c.pathParams ?? {}) };
    delete otherPathParams[paramName];

    const fetchOpts: string[] = [
      `method: '${c.method.toUpperCase()}'`,
      `headers: ${JSON.stringify(headers)}`,
    ];
    if (c.body !== undefined) fetchOpts.push(`data: ${JSON.stringify(c.body)}`);

    return `test(${JSON.stringify(c.name)}, async ({ request }) => {
  const petId = await createPet(request);
  const url = buildUrl(${JSON.stringify(c.path)}, { ${JSON.stringify(paramName)}: petId, ...${JSON.stringify(otherPathParams)} }, ${JSON.stringify(c.queryParams ?? {})});
  const res = await request.fetch(url, { ${fetchOpts.join(', ')} });
  expect(${expectedExpr}, \`expected status ${expected.join('|')} but got \${res.status()}: \${await res.text()}\`).toBeTruthy();
${assertionLines}
});`;
  }

  const fetchOpts: string[] = [
    `method: '${c.method.toUpperCase()}'`,
    `headers: ${JSON.stringify(headers)}`,
  ];
  if (c.body !== undefined) fetchOpts.push(`data: ${JSON.stringify(c.body)}`);

  return `test(${JSON.stringify(c.name)}, async ({ request }) => {
  const url = buildUrl(${JSON.stringify(c.path)}, ${JSON.stringify(c.pathParams ?? {})}, ${JSON.stringify(c.queryParams ?? {})});
  const res = await request.fetch(url, { ${fetchOpts.join(', ')} });
  expect(${expectedExpr}, \`expected status ${expected.join('|')} but got \${res.status()}: \${await res.text()}\`).toBeTruthy();
${assertionLines}
});`;
}

export function emitContractFixture(endpointId: string, cases: GeneratedTestCase[]): string {
  return JSON.stringify({ endpointId, cases }, null, 2);
}